    private static HashSet<MaterialIconKind> CreateGreen() =>
        "HandCoin FormatListChecks ReceiptText CalendarCheck ChartBar CashMultiple Wallet HandHeart CloudLock ShieldCheck CloudSyncOutline ContentSaveOutline BackupRestore Whatsapp MicrosoftExcel".Split(' ').Select(Enum.Parse<MaterialIconKind>).ToHashSet();

    private static void Add(Dictionary<MaterialIconKind, string> target, string alias, string geometry)
    {
        if (Enum.TryParse<MaterialIconKind>(alias, out var kind)) target[kind] = geometry;
    }
